:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --die-bg: #0f3460;
  --die-dot: #e94560;
  --focus: #f5c542;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  line-height: 1.5;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  background: var(--bg);
  color: var(--text);
  padding: 1rem;
}

.card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 2rem 1.5rem;
  max-width: 480px;
  width: 100%;
  box-shadow: 0 8px 32px rgba(0,0,0,0.4);
  border: 2px solid #2a2a4a;
}

h1 {
  font-size: 1.8rem;
  text-align: center;
  color: var(--accent);
  letter-spacing: 1px;
  margin-bottom: 0.25rem;
}

.subtitle {
  text-align: center;
  color: var(--muted);
  font-size: 1rem;
  margin-bottom: 1.5rem;
}

.controls {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  margin-bottom: 1.5rem;
}

.dice-count {
  border: 2px solid #2a2a4a;
  border-radius: 12px;
  padding: 0.75rem 1rem;
}

.dice-count legend {
  padding: 0 0.5rem;
  color: var(--muted);
  font-size: 0.95rem;
}

.radio-group {
  display: flex;
  gap: 1.5rem;
  justify-content: center;
}

.radio-label {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  cursor: pointer;
  font-size: 1.1rem;
  padding: 0.25rem 0.5rem;
  border-radius: 8px;
}

.radio-label:hover {
  background: rgba(233, 69, 96, 0.1);
}

.radio-label input[type="radio"] {
  width: 1.2rem;
  height: 1.2rem;
  accent-color: var(--accent);
  cursor: pointer;
}

.radio-label input[type="radio"]:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.roll-btn {
  font-size: 1.25rem;
  font-weight: 700;
  padding: 0.9rem 1.5rem;
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: 12px;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  letter-spacing: 0.5px;
}

.roll-btn:hover {
  background: #ff5c7a;
}

.roll-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
}

.roll-btn:active {
  transform: scale(0.97);
  background: #c73650;
}

.results {
  margin-bottom: 1.5rem;
}

.dice-container {
  display: flex;
  justify-content: center;
  gap: 1rem;
  flex-wrap: wrap;
  min-height: 80px;
  align-items: center;
  margin-bottom: 0.75rem;
}

.die {
  width: 72px;
  height: 72px;
  background: var(--die-bg);
  border: 3px solid var(--accent);
  border-radius: 12px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: repeat(3, 1fr);
  padding: 8px;
  gap: 4px;
  box-shadow: inset 0 0 0 2px rgba(255,255,255,0.05);
}

.die .dot {
  width: 100%;
  height: 100%;
  background: var(--die-dot);
  border-radius: 50%;
  opacity: 0;
}

.die .dot.visible {
  opacity: 1;
}

.total {
  text-align: center;
  font-size: 1.4rem;
  font-weight: 700;
  color: var(--text);
}

.history h2 {
  font-size: 1.1rem;
  color: var(--muted);
  margin-bottom: 0.5rem;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.history-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.history-list li {
  background: #0f1a30;
  padding: 0.5rem 0.75rem;
  border-radius: 8px;
  font-size: 0.95rem;
  display: flex;
  justify-content: space-between;
  border-left: 4px solid var(--accent);
}

.history-list .empty-history {
  color: var(--muted);
  font-style: italic;
  border-left-color: transparent;
  justify-content: center;
}

.history-list .roll-faces {
  color: var(--muted);
}

.history-list .roll-total {
  font-weight: 700;
  color: var(--accent);
}

@media (max-width: 400px) {
  .card {
    padding: 1.5rem 1rem;
  }
  h1 {
    font-size: 1.5rem;
  }
  .die {
    width: 60px;
    height: 60px;
    padding: 6px;
    gap: 3px;
  }
  .radio-group {
    gap: 1rem;
  }
}

const rollBtn = document.getElementById('rollBtn');
const diceContainer = document.getElementById('diceContainer');
const totalDisplay = document.getElementById('totalDisplay');
const historyList = document.getElementById('historyList');

const DOT_POSITIONS = {
  1: [4],
  2: [0, 8],
  3: [0, 4, 8],
  4: [0, 2, 6, 8],
  5: [0, 2, 4, 6, 8],
  6: [0, 2, 3, 5, 6, 8]
};

let history = [];

function getDiceCount() {
  const selected = document.querySelector('input[name="diceCount"]:checked');
  return selected ? parseInt(selected.value, 10) : 1;
}

function createDie(value) {
  const die = document.createElement('div');
  die.className = 'die';
  die.setAttribute('role', 'img');
  die.setAttribute('aria-label', 'Die showing ' + value);

  for (let i = 0; i < 9; i++) {
    const dot = document.createElement('span');
    dot.className = 'dot';
    if (DOT_POSITIONS[value].includes(i)) {
      dot.classList.add('visible');
    }
    die.appendChild(dot);
  }
  return die;
}

function renderDice(values) {
  diceContainer.innerHTML = '';
  values.forEach(v => diceContainer.appendChild(createDie(v)));
}

function renderTotal(total) {
  totalDisplay.textContent = 'Total: ' + total;
}

function renderHistory() {
  historyList.innerHTML = '';
  if (history.length === 0) {
    const li = document.createElement('li');
    li.className = 'empty-history';
    li.textContent = 'No rolls yet.';
    historyList.appendChild(li);
    return;
  }
  history.forEach(roll => {
    const li = document.createElement('li');
    const faces = document.createElement('span');
    faces.className = 'roll-faces';
    faces.textContent = roll.values.join(' + ');
    const total = document.createElement('span');
    total.className = 'roll-total';
    total.textContent = '= ' + roll.total;
    li.appendChild(faces);
    li.appendChild(total);
    historyList.appendChild(li);
  });
}

function rollDice() {
  const count = getDiceCount();
  const values = [];
  for (let i = 0; i < count; i++) {
    values.push(Math.floor(Math.random() * 6) + 1);
  }
  const total = values.reduce((a, b) => a + b, 0);

  renderDice(values);
  renderTotal(total);

  history.unshift({ values, total });
  if (history.length > 5) {
    history = history.slice(0, 5);
  }
  renderHistory();
}

rollBtn.addEventListener('click', rollDice);

// Initialize empty state
renderHistory();
